// fma / fmaf with a single rounding (card: runtime; header
// runtime/include/ocu_fma_exact.h), checked on kernels (CPU path and
// NVIDIA GPU), on the host's std::fma when ocu_cudart is linked, and on the
// header's software functions directly.
//
// Expected values come from fma_exact_table.h, generated by
// gen_fma_tables.py with exact rational arithmetic from IEEE 754-2019
// 5.4.1 (fusedMultiplyAdd), 4.3 (rounding directions), 6.3 (sign of zero),
// 7.4 (overflow).  The table holds, per format: signed zeros, units, the
// smallest and largest numbers in all combinations; random operands over the
// whole exponent range; products and addends around the fast-path limits
// 2^-400 and 2^400 (double) and the 2^-800 product range; cancellation
// (c = -RN(a*b) +- k ulp); exact ties between the product and half an ulp of
// c; subnormal and half-way cases; overflow.  Each row has the result for
// rn, rz, ru, rd.
//
// Literal values from the card / header are checked here as well, in C++
// hex-float syntax, so the generator itself is not the only authority.
//
// Usage: fma_exact_test [powf]   (powf: only the powf bound)
#include <cuda_runtime.h>

#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <cmath>

#include "fma_exact_table.h"
#include "powf_table.h"

#include "ocu_fma_exact.h"

// The header's own functions are host functions only on the CPU path (on the
// NVIDIA path they are device functions of the runtime headers).
#if defined(OCU_CPU_PATH)
#define HAVE_HDR 1
#include "ocu_device_math.h"
#endif

#define CK(x)                                                                              \
    do {                                                                                   \
        cudaError_t e_ = (x);                                                              \
        if (e_ != cudaSuccess) {                                                           \
            printf("CUDA error %s at line %d\n", cudaGetErrorString(e_), __LINE__);       \
            exit(2);                                                                       \
        }                                                                                  \
    } while (0)

static long g_checks, g_failed;

static float F(uint32_t b) { float f; memcpy(&f, &b, 4); return f; }
static double D(uint64_t b) { double d; memcpy(&d, &b, 8); return d; }
static uint32_t BF(float f) { uint32_t b; memcpy(&b, &f, 4); return b; }
static uint64_t BD(double d) { uint64_t b; memcpy(&b, &d, 8); return b; }

__host__ __device__ static inline float dF(uint32_t b) { union { uint32_t u; float f; } v; v.u = b; return v.f; }
__host__ __device__ static inline uint32_t dBF(float f) { union { uint32_t u; float f; } v; v.f = f; return v.u; }
__host__ __device__ static inline double dD(uint64_t b) { union { uint64_t u; double f; } v; v.u = b; return v.f; }
__host__ __device__ static inline uint64_t dBD(double f) { union { uint64_t u; double f; } v; v.f = f; return v.u; }

// per-function failure counts
struct Tally {
    const char *name;
    long n, bad;
};

static void note_f(Tally &t, uint32_t got, uint32_t want, uint32_t a, uint32_t b, uint32_t c)
{
    t.n++;
    g_checks++;
    if (got != want) {
        g_failed++;
        if (t.bad++ < 4)
            printf("FAIL %s(%a, %a, %a) = %a (0x%08x), exact %a (0x%08x)\n", t.name, F(a), F(b), F(c), F(got), got, F(want), want);
    }
}

static void note_d(Tally &t, uint64_t got, uint64_t want, uint64_t a, uint64_t b, uint64_t c)
{
    t.n++;
    g_checks++;
    if (got != want) {
        g_failed++;
        if (t.bad++ < 4)
            printf("FAIL %s(%a, %a, %a) = %a (0x%016llx), exact %a (0x%016llx)\n", t.name, D(a), D(b), D(c), D(got),
                   (unsigned long long)got, D(want), (unsigned long long)want);
    }
}

// ---- kernels ---------------------------------------------------------------------

__global__ void kern_f(const uint32_t *a, const uint32_t *b, const uint32_t *c, uint32_t *out, int n)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;
    float x = dF(a[i]), y = dF(b[i]), z = dF(c[i]);
    out[i * 6 + 0] = dBF(fmaf(x, y, z));
    out[i * 6 + 1] = dBF(__fmaf_rn(x, y, z));
    out[i * 6 + 2] = dBF(__fmaf_rz(x, y, z));
    out[i * 6 + 3] = dBF(__fmaf_ru(x, y, z));
    out[i * 6 + 4] = dBF(__fmaf_rd(x, y, z));
    out[i * 6 + 5] = dBF(fma(x, y, z)); // the float overload
}

__global__ void kern_d(const uint64_t *a, const uint64_t *b, const uint64_t *c, uint64_t *out, int n)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;
    double x = dD(a[i]), y = dD(b[i]), z = dD(c[i]);
    out[i * 5 + 0] = dBD(fma(x, y, z));
    out[i * 5 + 1] = dBD(__fma_rn(x, y, z));
    out[i * 5 + 2] = dBD(__fma_rz(x, y, z));
    out[i * 5 + 3] = dBD(__fma_ru(x, y, z));
    out[i * 5 + 4] = dBD(__fma_rd(x, y, z));
}

template <class T>
static T *to_dev(const T *h, size_t n)
{
    T *d;
    CK(cudaMalloc(&d, n * sizeof(T)));
    CK(cudaMemcpy(d, h, n * sizeof(T), cudaMemcpyHostToDevice));
    return d;
}

// ---- the table, on kernels and on the host -----------------------------------------

static Tally kf[6] = {{"kernel fmaf", 0, 0}, {"kernel __fmaf_rn", 0, 0}, {"kernel __fmaf_rz", 0, 0},
                      {"kernel __fmaf_ru", 0, 0}, {"kernel __fmaf_rd", 0, 0}, {"kernel fma(float)", 0, 0}};
static Tally kd[5] = {{"kernel fma", 0, 0}, {"kernel __fma_rn", 0, 0}, {"kernel __fma_rz", 0, 0},
                      {"kernel __fma_ru", 0, 0}, {"kernel __fma_rd", 0, 0}};
static Tally hf[3] = {{"host std::fma(float)", 0, 0}, {"host ::fmaf", 0, 0}, {"host ocu_fmaf_rn", 0, 0}};
static Tally hd[3] = {{"host std::fma(double)", 0, 0}, {"host ::fma", 0, 0}, {"host ocu_fma_rn", 0, 0}};
static Tally sf[4] = {{"ocu_fmaf_soft rn", 0, 0}, {"ocu_fmaf_soft rz", 0, 0}, {"ocu_fmaf_soft ru", 0, 0}, {"ocu_fmaf_soft rd", 0, 0}};
static Tally sd[4] = {{"ocu_fma_soft rn", 0, 0}, {"ocu_fma_soft rz", 0, 0}, {"ocu_fma_soft ru", 0, 0}, {"ocu_fma_soft rd", 0, 0}};

static void run_table_f()
{
    int n = fma_rows_f_n;
    uint32_t *ha = (uint32_t *)malloc(n * 4), *hb = (uint32_t *)malloc(n * 4), *hc = (uint32_t *)malloc(n * 4);
    for (int i = 0; i < n; i++) {
        ha[i] = fma_rows_f[i].a;
        hb[i] = fma_rows_f[i].b;
        hc[i] = fma_rows_f[i].c;
    }
    uint32_t *da = to_dev(ha, n), *db = to_dev(hb, n), *dc = to_dev(hc, n), *dout;
    CK(cudaMalloc(&dout, (size_t)n * 6 * 4));
    kern_f<<<(n + 127) / 128, 128>>>(da, db, dc, dout, n);
    CK(cudaGetLastError());
    CK(cudaDeviceSynchronize());
    uint32_t *out = (uint32_t *)malloc((size_t)n * 6 * 4);
    CK(cudaMemcpy(out, dout, (size_t)n * 6 * 4, cudaMemcpyDeviceToHost));
    long zero = 0, sub = 0, inf = 0;
    for (int i = 0; i < n; i++) {
        const FmaRowF &r = fma_rows_f[i];
        uint32_t want[4] = {r.rn, r.rz, r.ru, r.rd};
        // kernel: fmaf and __fmaf_rn and fma are round to nearest; then rz, ru, rd
        note_f(kf[0], out[i * 6 + 0], r.rn, r.a, r.b, r.c);
        note_f(kf[1], out[i * 6 + 1], r.rn, r.a, r.b, r.c);
        note_f(kf[2], out[i * 6 + 2], r.rz, r.a, r.b, r.c);
        note_f(kf[3], out[i * 6 + 3], r.ru, r.a, r.b, r.c);
        note_f(kf[4], out[i * 6 + 4], r.rd, r.a, r.b, r.c);
        note_f(kf[5], out[i * 6 + 5], r.rn, r.a, r.b, r.c);
        volatile float x = F(r.a), y = F(r.b), z = F(r.c);
        note_f(hf[0], BF(std::fma((float)x, (float)y, (float)z)), r.rn, r.a, r.b, r.c);
        note_f(hf[1], BF(::fmaf(x, y, z)), r.rn, r.a, r.b, r.c);
#ifdef HAVE_HDR
        note_f(hf[2], BF(ocu_fmaf_rn(x, y, z)), r.rn, r.a, r.b, r.c);
#endif
#ifdef HAVE_HDR
        for (int m = 0; m < 4; m++) note_f(sf[m], BF(ocu_fmaf_soft(x, y, z, m)), want[m], r.a, r.b, r.c);
#endif
        uint32_t e = r.rn & 0x7f800000u;
        if ((r.rn & 0x7fffffffu) == 0) zero++;
        else if (e == 0) sub++;
        else if (e == 0x7f800000u) inf++;
    }
    printf("float table: %d rows (results: %ld zero, %ld subnormal, %ld infinite under rn)\n", n, zero, sub, inf);
    free(ha); free(hb); free(hc); free(out);
    CK(cudaFree(da)); CK(cudaFree(db)); CK(cudaFree(dc)); CK(cudaFree(dout));
}

static void run_table_d()
{
    int n = fma_rows_d_n;
    uint64_t *ha = (uint64_t *)malloc(n * 8), *hb = (uint64_t *)malloc(n * 8), *hc = (uint64_t *)malloc(n * 8);
    for (int i = 0; i < n; i++) {
        ha[i] = fma_rows_d[i].a;
        hb[i] = fma_rows_d[i].b;
        hc[i] = fma_rows_d[i].c;
    }
    uint64_t *da = to_dev(ha, n), *db = to_dev(hb, n), *dc = to_dev(hc, n), *dout;
    CK(cudaMalloc(&dout, (size_t)n * 5 * 8));
    kern_d<<<(n + 127) / 128, 128>>>(da, db, dc, dout, n);
    CK(cudaGetLastError());
    CK(cudaDeviceSynchronize());
    uint64_t *out = (uint64_t *)malloc((size_t)n * 5 * 8);
    CK(cudaMemcpy(out, dout, (size_t)n * 5 * 8, cudaMemcpyDeviceToHost));
    long zero = 0, sub = 0, inf = 0;
    for (int i = 0; i < n; i++) {
        const FmaRowD &r = fma_rows_d[i];
        uint64_t want[4] = {r.rn, r.rz, r.ru, r.rd};
        note_d(kd[0], out[i * 5 + 0], r.rn, r.a, r.b, r.c);
        note_d(kd[1], out[i * 5 + 1], r.rn, r.a, r.b, r.c);
        note_d(kd[2], out[i * 5 + 2], r.rz, r.a, r.b, r.c);
        note_d(kd[3], out[i * 5 + 3], r.ru, r.a, r.b, r.c);
        note_d(kd[4], out[i * 5 + 4], r.rd, r.a, r.b, r.c);
        volatile double x = D(r.a), y = D(r.b), z = D(r.c);
        note_d(hd[0], BD(std::fma((double)x, (double)y, (double)z)), r.rn, r.a, r.b, r.c);
        note_d(hd[1], BD(::fma(x, y, z)), r.rn, r.a, r.b, r.c);
#ifdef HAVE_HDR
        note_d(hd[2], BD(ocu_fma_rn(x, y, z)), r.rn, r.a, r.b, r.c);
#endif
#if defined(OCU_FMA_HAVE_SOFT_DOUBLE) && defined(HAVE_HDR)
#ifdef HAVE_HDR
        for (int m = 0; m < 4; m++) note_d(sd[m], BD(ocu_fma_soft(x, y, z, m)), want[m], r.a, r.b, r.c);
#endif
#endif
        uint64_t e = r.rn & 0x7ff0000000000000ull;
        if ((r.rn & 0x7fffffffffffffffull) == 0) zero++;
        else if (e == 0) sub++;
        else if (e == 0x7ff0000000000000ull) inf++;
    }
    printf("double table: %d rows (results: %ld zero, %ld subnormal, %ld infinite under rn)\n", n, zero, sub, inf);
    free(ha); free(hb); free(hc); free(out);
    CK(cudaFree(da)); CK(cudaFree(db)); CK(cudaFree(dc)); CK(cudaFree(dout));
}

// ---- values written out by hand (card / header) ------------------------------------

static void literal(const char *what, bool ok, double got, double want)
{
    g_checks++;
    if (!ok) {
        g_failed++;
        printf("FAIL %s: got %a want %a\n", what, got, want);
    }
}

static void run_literals()
{
    volatile float a = 0x1.02fbdap+0f, b = 0x1.fffffep-1f, c = -0x1.02fbd8p+0f;
    // single rounding: the intermediate product rounded to float gives 0x1.fa085p-25 (MinGW's fmaf)
    literal("host fmaf single rounding sample", std::fma((float)a, (float)b, (float)c) == 0x1.fa084cp-25f,
            std::fma((float)a, (float)b, (float)c), 0x1.fa084cp-25f);
    literal("host fmaf single rounding sample (::fmaf)", ::fmaf(a, b, c) == 0x1.fa084cp-25f, ::fmaf(a, b, c), 0x1.fa084cp-25f);
    volatile float t1 = 0x1p-126f, t2 = 0x1p-24f, t3 = 0x1p-149f;
    literal("host fmaf subnormal tie -> even", std::fma((float)t1, (float)t2, (float)t3) == 0x1p-148f,
            std::fma((float)t1, (float)t2, (float)t3), 0x1p-148f);
    volatile double d1 = 0x1p-1022, d2 = 0x1p-53, d3 = 0x1p-1074;
    literal("host fma subnormal tie -> even", std::fma((double)d1, (double)d2, (double)d3) == 0x0.0000000000002p-1022,
            std::fma((double)d1, (double)d2, (double)d3), 0x0.0000000000002p-1022);
    // cancellation: (1 + 2^-30)(1 - 2^-30) - 1 = -2^-60 exactly; the product alone rounds to 1
    volatile double e1 = 1.0 + 0x1p-30, e2 = 1.0 - 0x1p-30;
    literal("host fma cancellation", std::fma((double)e1, (double)e2, -1.0) == -0x1p-60, std::fma((double)e1, (double)e2, -1.0), -0x1p-60);
    volatile float g1 = 1.0f + 0x1p-12f, g2 = 1.0f - 0x1p-12f;
    literal("host fmaf cancellation", std::fma((float)g1, (float)g2, -1.0f) == -0x1p-24f, std::fma((float)g1, (float)g2, -1.0f), -0x1p-24f);
    // largest finite times two minus itself: finite in unbounded range (IEEE 754 5.4.1)
    volatile double mx = 0x1.fffffffffffffp1023;
    literal("host fma max*2-max", std::fma((double)mx, 2.0, -(double)mx) == 0x1.fffffffffffffp1023, std::fma((double)mx, 2.0, -(double)mx), 0x1.fffffffffffffp1023);
    volatile float mxf = 0x1.fffffep127f;
    literal("host fmaf max*2-max", std::fma((float)mxf, 2.0f, -(float)mxf) == 0x1.fffffep127f, std::fma((float)mxf, 2.0f, -(float)mxf), 0x1.fffffep127f);
#if defined(OCU_FMA_HAVE_SOFT_DOUBLE) && defined(HAVE_HDR)
    // the header's own samples
    literal("soft fmaf sample", ocu_fmaf_soft(a, b, c, OCU_FMA_RN) == 0x1.fa084cp-25f, ocu_fmaf_soft(a, b, c, OCU_FMA_RN), 0x1.fa084cp-25f);
    literal("soft fma tie", ocu_fma_soft(d1, d2, d3, OCU_FMA_RN) == 0x0.0000000000002p-1022, ocu_fma_soft(d1, d2, d3, OCU_FMA_RN), 0x0.0000000000002p-1022);
    // overflow with the four directions (IEEE 754-2019 7.4)
    literal("soft overflow rn", std::isinf(ocu_fma_soft(mx, 2.0, 0.0, OCU_FMA_RN)) && ocu_fma_soft(mx, 2.0, 0.0, OCU_FMA_RN) > 0, ocu_fma_soft(mx, 2.0, 0.0, OCU_FMA_RN), INFINITY);
    literal("soft overflow rz", ocu_fma_soft(mx, 2.0, 0.0, OCU_FMA_RZ) == 0x1.fffffffffffffp1023, ocu_fma_soft(mx, 2.0, 0.0, OCU_FMA_RZ), 0x1.fffffffffffffp1023);
    literal("soft overflow ru", std::isinf(ocu_fma_soft(mx, 2.0, 0.0, OCU_FMA_RU)), ocu_fma_soft(mx, 2.0, 0.0, OCU_FMA_RU), INFINITY);
    literal("soft overflow rd", ocu_fma_soft(mx, 2.0, 0.0, OCU_FMA_RD) == 0x1.fffffffffffffp1023, ocu_fma_soft(mx, 2.0, 0.0, OCU_FMA_RD), 0x1.fffffffffffffp1023);
    literal("soft overflow rd negative", std::isinf(ocu_fma_soft(-mx, 2.0, 0.0, OCU_FMA_RD)) && ocu_fma_soft(-mx, 2.0, 0.0, OCU_FMA_RD) < 0, ocu_fma_soft(-mx, 2.0, 0.0, OCU_FMA_RD), -INFINITY);
    literal("soft overflow ru negative", ocu_fma_soft(-mx, 2.0, 0.0, OCU_FMA_RU) == -0x1.fffffffffffffp1023, ocu_fma_soft(-mx, 2.0, 0.0, OCU_FMA_RU), -0x1.fffffffffffffp1023);
#endif
}

// ---- infinities and NaNs ---------------------------------------------------------------

struct Special {
    int width;      // 32 or 64
    uint64_t a, b, c;
    int want;       // 0: NaN, 1: +inf, 2: -inf, 3: exact bits in `bits`
    uint64_t bits;
    const char *what;
};

#define F_INF 0x7f800000ull
#define F_NINF 0xff800000ull
#define F_QNAN 0x7fc00000ull
#define F_SNAN 0x7fa00000ull
#define F_ONE 0x3f800000ull
#define F_NONE 0xbf800000ull
#define F_TWO 0x40000000ull
#define F_THREE 0x40400000ull
#define F_MAX 0x7f7fffffull
#define F_NMAX 0xff7fffffull
#define D_INF 0x7ff0000000000000ull
#define D_NINF 0xfff0000000000000ull
#define D_QNAN 0x7ff8000000000000ull
#define D_SNAN 0x7ff4000000000000ull
#define D_ONE 0x3ff0000000000000ull
#define D_NONE 0xbff0000000000000ull
#define D_TWO 0x4000000000000000ull
#define D_THREE 0x4008000000000000ull
#define D_MAX 0x7fefffffffffffffull
#define D_NMAX 0xffefffffffffffffull

#define SPEC(w, P, a, b, c, want, bits, what)                                              \
    {w, P##a, P##b, P##c, want, bits, what}

static const Special specials[] = {
#define BOTH(P, w)                                                                                       \
    {w, P##_INF, 0, P##_ONE, 0, 0, "inf * 0 + 1"},                                                       \
    {w, 0, P##_INF, P##_ONE, 0, 0, "0 * inf + 1"},                                                       \
    {w, P##_NINF, 0, P##_THREE, 0, 0, "-inf * 0 + 3"},                                                   \
    {w, P##_INF, 0, P##_QNAN, 0, 0, "inf * 0 + qNaN"},                                                   \
    {w, P##_INF, P##_ONE, P##_NINF, 0, 0, "inf * 1 - inf"},                                              \
    {w, P##_NINF, P##_ONE, P##_INF, 0, 0, "-inf * 1 + inf"},                                             \
    {w, P##_INF, P##_NONE, P##_INF, 0, 0, "inf * -1 + inf"},                                             \
    {w, P##_INF, P##_INF, P##_NINF, 0, 0, "inf * inf - inf"},                                            \
    {w, P##_NINF, P##_NINF, P##_NINF, 0, 0, "-inf * -inf - inf"},                                        \
    {w, P##_INF, P##_ONE, P##_INF, 1, 0, "inf * 1 + inf"},                                               \
    {w, P##_NINF, P##_ONE, P##_NINF, 2, 0, "-inf * 1 - inf"},                                            \
    {w, P##_INF, P##_TWO, P##_THREE, 1, 0, "inf * 2 + 3"},                                               \
    {w, P##_NINF, P##_TWO, P##_THREE, 2, 0, "-inf * 2 + 3"},                                             \
    {w, P##_TWO, P##_THREE, P##_INF, 1, 0, "2 * 3 + inf"},                                               \
    {w, P##_TWO, P##_THREE, P##_NINF, 2, 0, "2 * 3 - inf"},                                              \
    {w, P##_INF, P##_NINF, P##_THREE, 2, 0, "inf * -inf + 3"},                                           \
    {w, P##_NINF, P##_NINF, P##_THREE, 1, 0, "-inf * -inf + 3"},                                         \
    {w, P##_QNAN, P##_ONE, P##_ONE, 0, 0, "qNaN * 1 + 1"},                                               \
    {w, P##_ONE, P##_QNAN, P##_ONE, 0, 0, "1 * qNaN + 1"},                                               \
    {w, P##_ONE, P##_ONE, P##_QNAN, 0, 0, "1 * 1 + qNaN"},                                               \
    {w, P##_SNAN, P##_ONE, P##_ONE, 0, 0, "sNaN * 1 + 1"},                                               \
    {w, P##_ONE, P##_SNAN, P##_ONE, 0, 0, "1 * sNaN + 1"},                                               \
    {w, P##_ONE, P##_ONE, P##_SNAN, 0, 0, "1 * 1 + sNaN"},                                               \
    {w, 0, 0, P##_QNAN, 0, 0, "0 * 0 + qNaN"},                                                           \
    {w, P##_MAX, P##_TWO, P##_NINF, 2, 0, "max * 2 - inf"},                                              \
    {w, P##_MAX, P##_TWO, P##_NMAX, 3, P##_MAX, "max * 2 - max = max (unbounded range)"},                \
    {w, P##_NMAX, P##_TWO, P##_MAX, 3, P##_NMAX, "-max * 2 + max = -max (unbounded range)"},
    BOTH(F, 32)
    BOTH(D, 64)
};

static bool is_nan_q(int width, uint64_t v, bool *quiet)
{
    if (width == 32) {
        *quiet = (v & 0x400000u) != 0;
        return (v & 0x7f800000u) == 0x7f800000u && (v & 0x7fffffu) != 0;
    }
    *quiet = (v & 0x8000000000000ull) != 0;
    return (v & 0x7ff0000000000000ull) == 0x7ff0000000000000ull && (v & 0xfffffffffffffull) != 0;
}

static void check_special(const Special &s, const char *fn, uint64_t got)
{
    g_checks++;
    bool quiet = false;
    bool nan = is_nan_q(s.width, got, &quiet);
    uint64_t inf = s.width == 32 ? 0x7f800000ull : 0x7ff0000000000000ull;
    uint64_t ninf = s.width == 32 ? 0xff800000ull : 0xfff0000000000000ull;
    bool ok;
    switch (s.want) {
    case 0: ok = nan && quiet; break; // IEEE 754-2019 7.2: a quiet NaN
    case 1: ok = got == inf; break;
    case 2: ok = got == ninf; break;
    default: ok = got == s.bits; break;
    }
    if (!ok) {
        g_failed++;
        printf("FAIL special %s [%s, %d bit]: got 0x%llx\n", fn, s.what, s.width, (unsigned long long)got);
    }
}

static void run_specials()
{
    int nf = 0, nd = 0;
    for (const Special &s : specials) (s.width == 32 ? nf : nd)++;
    uint32_t *fa = (uint32_t *)malloc(nf * 4), *fb = (uint32_t *)malloc(nf * 4), *fc = (uint32_t *)malloc(nf * 4);
    uint64_t *xa = (uint64_t *)malloc(nd * 8), *xb = (uint64_t *)malloc(nd * 8), *xc = (uint64_t *)malloc(nd * 8);
    int i = 0, j = 0;
    for (const Special &s : specials) {
        if (s.width == 32) { fa[i] = (uint32_t)s.a; fb[i] = (uint32_t)s.b; fc[i] = (uint32_t)s.c; i++; }
        else { xa[j] = s.a; xb[j] = s.b; xc[j] = s.c; j++; }
    }
    uint32_t *da = to_dev(fa, nf), *db = to_dev(fb, nf), *dc = to_dev(fc, nf), *dout;
    CK(cudaMalloc(&dout, (size_t)nf * 6 * 4));
    kern_f<<<1, 128>>>(da, db, dc, dout, nf);
    CK(cudaGetLastError());
    CK(cudaDeviceSynchronize());
    uint32_t *out = (uint32_t *)malloc((size_t)nf * 6 * 4);
    CK(cudaMemcpy(out, dout, (size_t)nf * 6 * 4, cudaMemcpyDeviceToHost));
    uint64_t *ea = to_dev(xa, nd), *eb = to_dev(xb, nd), *ec = to_dev(xc, nd), *eout;
    CK(cudaMalloc(&eout, (size_t)nd * 5 * 8));
    kern_d<<<1, 128>>>(ea, eb, ec, eout, nd);
    CK(cudaGetLastError());
    CK(cudaDeviceSynchronize());
    uint64_t *outd = (uint64_t *)malloc((size_t)nd * 5 * 8);
    CK(cudaMemcpy(outd, eout, (size_t)nd * 5 * 8, cudaMemcpyDeviceToHost));
    static const char *nf_names[6] = {"kernel fmaf", "kernel __fmaf_rn", "kernel __fmaf_rz", "kernel __fmaf_ru", "kernel __fmaf_rd", "kernel fma(float)"};
    static const char *nd_names[5] = {"kernel fma", "kernel __fma_rn", "kernel __fma_rz", "kernel __fma_ru", "kernel __fma_rd"};
    i = j = 0;
    for (const Special &s : specials) {
        if (s.width == 32) {
            for (int k = 0; k < 6; k++) check_special(s, nf_names[k], out[i * 6 + k]);
            volatile float x = F((uint32_t)s.a), y = F((uint32_t)s.b), z = F((uint32_t)s.c);
            check_special(s, "host std::fma(float)", BF(std::fma((float)x, (float)y, (float)z)));
            check_special(s, "host ::fmaf", BF(::fmaf(x, y, z)));
#ifdef HAVE_HDR
            check_special(s, "host ocu_fmaf_rn", BF(ocu_fmaf_rn(x, y, z)));
#endif
#ifdef HAVE_HDR
            for (int m = 0; m < 4; m++) check_special(s, "ocu_fmaf_soft", BF(ocu_fmaf_soft(x, y, z, m)));
#endif
            i++;
        } else {
            for (int k = 0; k < 5; k++) check_special(s, nd_names[k], outd[j * 5 + k]);
            volatile double x = D(s.a), y = D(s.b), z = D(s.c);
            check_special(s, "host std::fma(double)", BD(std::fma((double)x, (double)y, (double)z)));
            check_special(s, "host ::fma", BD(::fma(x, y, z)));
#ifdef HAVE_HDR
            check_special(s, "host ocu_fma_rn", BD(ocu_fma_rn(x, y, z)));
#endif
#if defined(OCU_FMA_HAVE_SOFT_DOUBLE) && defined(HAVE_HDR)
            for (int m = 0; m < 4; m++) check_special(s, "ocu_fma_soft", BD(ocu_fma_soft(x, y, z, m)));
#endif
            j++;
        }
    }
    printf("specials: %d float and %d double cases\n", nf, nd);
    free(fa); free(fb); free(fc); free(xa); free(xb); free(xc); free(out); free(outd);
    CK(cudaFree(da)); CK(cudaFree(db)); CK(cudaFree(dc)); CK(cudaFree(dout));
    CK(cudaFree(ea)); CK(cudaFree(eb)); CK(cudaFree(ec)); CK(cudaFree(eout));
}

// ---- powf within the documented bound ---------------------------------------------------

__global__ void kern_pow(const uint32_t *x, const uint32_t *y, uint32_t *out, int n)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) out[i] = dBF(powf(dF(x[i]), dF(y[i])));
}

// distance in representable floats between two finite floats of any sign
static long ulp_dist(uint32_t p, uint32_t q)
{
    auto key = [](uint32_t b) -> long { return (b & 0x80000000u) ? -(long)(b & 0x7fffffffu) : (long)b; };
    long d = key(p) - key(q);
    return d < 0 ? -d : d;
}

static void run_powf()
{
    // CUDA Math API: powf has a maximum error of 4 ulp (single precision).
    const long BOUND = 4;
    int n = pow_rows_n;
    uint32_t *hx = (uint32_t *)malloc(n * 4), *hy = (uint32_t *)malloc(n * 4);
    for (int i = 0; i < n; i++) { hx[i] = pow_rows[i].x; hy[i] = pow_rows[i].y; }
    uint32_t *dx = to_dev(hx, n), *dy = to_dev(hy, n), *dout;
    CK(cudaMalloc(&dout, (size_t)n * 4));
    kern_pow<<<(n + 127) / 128, 128>>>(dx, dy, dout, n);
    CK(cudaGetLastError());
    CK(cudaDeviceSynchronize());
    uint32_t *out = (uint32_t *)malloc((size_t)n * 4);
    CK(cudaMemcpy(out, dout, (size_t)n * 4, cudaMemcpyDeviceToHost));
    long worst_k = 0, worst_h = 0, worst_m = 0;
    long bad_k = 0, bad_h = 0, bad_m = 0;
    for (int i = 0; i < n; i++) {
        const PowRow &r = pow_rows[i];
        long dk = ulp_dist(out[i], r.want);
        volatile float x = F(r.x), y = F(r.y);
        long dh = ulp_dist(BF(powf(x, y)), r.want);
        g_checks += 2;
#ifdef HAVE_HDR
        // the float math functions of ocu_device_math.h (the NVIDIA device code's), on the host
        long dm = ulp_dist(BF(ocu_dm::powf(x, y)), r.want);
        g_checks++;
        if (dm > worst_m) worst_m = dm;
        if (dm > BOUND) {
            g_failed++;
            if (bad_m++ < 4) printf("FAIL ocu_dm::powf(%a, %a) = %a, correctly rounded %a (%ld ulp apart)\n", F(r.x), F(r.y), ocu_dm::powf(x, y), F(r.want), dm);
        }
#endif
        if (dk > worst_k) worst_k = dk;
        if (dh > worst_h) worst_h = dh;
        if (dk > BOUND) {
            g_failed++;
            if (bad_k++ < 4) printf("FAIL kernel powf(%a, %a) = %a, correctly rounded %a (%ld ulp apart)\n", F(r.x), F(r.y), F(out[i]), F(r.want), dk);
        }
        if (dh > BOUND) {
            g_failed++;
            if (bad_h++ < 4) printf("FAIL host powf(%a, %a) = %a, correctly rounded %a (%ld ulp apart)\n", F(r.x), F(r.y), powf(x, y), F(r.want), dh);
        }
    }
    printf("powf: %d points, largest distance to the correctly rounded result: kernel %ld ulp, host %ld ulp, ocu_dm::powf %ld ulp (bound %ld)\n", n, worst_k, worst_h, worst_m, BOUND);
    free(hx); free(hy); free(out);
    CK(cudaFree(dx)); CK(cudaFree(dy)); CK(cudaFree(dout));
}

int main(int argc, char **argv)
{
    int ndev = 0;
    CK(cudaGetDeviceCount(&ndev));
    if (ndev == 0) {
        printf("no device\n");
        return 2;
    }
    bool only_pow = argc > 1 && strcmp(argv[1], "powf") == 0;
#if defined(OCU_LIBM_FMA_EXACT)
    printf("OCU_LIBM_FMA_EXACT=%d OCU_FMA_BUILTIN=%d\n", (int)OCU_LIBM_FMA_EXACT, (int)OCU_FMA_BUILTIN);
#endif
    if (only_pow) {
        run_powf();
    } else {
        run_literals();
        run_specials();
        run_table_f();
        run_table_d();
        for (Tally &t : kf) printf("  %-24s %6ld rows, %ld wrong\n", t.name, t.n, t.bad);
        for (Tally &t : kd) printf("  %-24s %6ld rows, %ld wrong\n", t.name, t.n, t.bad);
        for (Tally &t : hf) printf("  %-24s %6ld rows, %ld wrong\n", t.name, t.n, t.bad);
        for (Tally &t : hd) printf("  %-24s %6ld rows, %ld wrong\n", t.name, t.n, t.bad);
        for (Tally &t : sf) printf("  %-24s %6ld rows, %ld wrong\n", t.name, t.n, t.bad);
        for (Tally &t : sd) printf("  %-24s %6ld rows, %ld wrong\n", t.name, t.n, t.bad);
    }
    printf("fma_exact_test: %ld checks, %ld failed\n", g_checks, g_failed);
    return g_failed ? 1 : 0;
}
